mapper.select:
select #{uid} uid,s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type, s.signing_data, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.state,st.state_name,s.file,s.open_file,s.mid_file,s.over_file, s.subject_source from sci_horizontal_apply_vertical s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sys_approval_state st on s.state = st.state_code where 1=1 and YEAR(DATE_ADD(s.signing_data,INTERVAL 1 MONTH)) = #{year} and top_name like concat('%', #{topName}, '%') and top_number = #{topNumber} and u.user_name like concat('%', #{userName}, '%') and d.dept_name like concat('%', #{dname}, '%') and p.dept_name like concat('%', #{yname}, '%') and state = #{state}
and d.dept_id = #{userynameId}
and p.dept_id = #{userynameId}
and p.dept_id = #{userynameId}
${params.dataScope} order by case -- 草稿箱 when state = 'VERTICAL_APPLY_DRAFT' or state = 'VERTICAL_OVER_DRAFT' then 1 -- 被驳回 when state = 'VERTICAL_APPLY_REJECTED' or state = 'VERTICAL_OVER_REJECTED' then 2 -- 申请结项 when state = 'VERTICAL_APPLY_PASSED' then 3 -- 审核中 when state in ('VERTICAL_APPLY_JYS_AUDIT','VERTICAL_APPLY_XY_AUDIT','VERTICAL_APPLY_KYC_AUDIT','VERTICAL_OVER_JYS_AUDIT','VERTICAL_OVER_XY_AUDIT','VERTICAL_OVER_KYC_AUDIT') then 4 -- 已完成 when state = 'VERTICAL_OVER_PASSED' then 5 end, s.createtime desc

select #{uid} uid,s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type, s.signing_data, s.validity_data, s.first_person_id, s.second_person_id, s.third_person_id, s.fourth_person_id, concat( s.amount,'万') amount, s.state,st.state_name,s.file,s.open_file,s.mid_file,s.over_file, s.subject_source from sci_horizontal_apply_vertical s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sys_approval_state st on s.state = st.state_code where s.state in ('VERTICAL_OVER_DRAFT','VERTICAL_OVER_JYS_AUDIT','VERTICAL_OVER_XY_AUDIT','VERTICAL_OVER_KYC_AUDIT','VERTICAL_OVER_REJECTED')
AND YEAR(DATE_ADD(COALESCE(s.validity_data, s.signing_data), INTERVAL 1 MONTH)) = #{year}
and top_name like concat('%', #{topName}, '%') and p.dept_name like concat('%', #{yname}, '%') and d.dept_name like concat('%', #{dname}, '%') and u.user_name like concat('%', #{userName}, '%') and state = #{state} ${params.dataScope} order by case -- 被驳回 when state = 'VERTICAL_OVER_REJECTED' then 2 -- 审核中 when state in ('VERTICAL_OVER_JYS_AUDIT','VERTICAL_OVER_XY_AUDIT','VERTICAL_OVER_KYC_AUDIT') then 4 end, s.createtime desc

select #{uid} uid,s.id,u.user_name userName,d.dept_id,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type, s.signing_data, s.validity_data, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.state,st.state_name,s.file,s.open_file,s.mid_file,s.over_file, s.subject_source from sci_horizontal_apply_vertical s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sys_approval_state st on s.state = st.state_code where s.state in ('VERTICAL_OVER_JYS_AUDIT','VERTICAL_OVER_XY_AUDIT','VERTICAL_OVER_KYC_AUDIT','VERTICAL_OVER_REJECTED')
AND YEAR(DATE_ADD(COALESCE(s.validity_data, s.signing_data), INTERVAL 1 MONTH)) = #{year}
and top_name like concat('%', #{topName}, '%') and u.user_name like concat('%', #{userName}, '%') and state = #{state} ${params.dataScope} order by case -- 待教研室审核 when state = 'VERTICAL_OVER_JYS_AUDIT' then 1 -- 待学院审核 when state = 'VERTICAL_OVER_XY_AUDIT' then 2 -- 待科研处审核 when state = 'VERTICAL_OVER_KYC_AUDIT' then 3 end, s.createtime desc

select #{uid} uid,s.id,u.user_name userName,d.dept_name dname,p.dept_id ynameId,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type, s.signing_data, s.validity_data, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.state,st.state_name,s.file,s.open_file,s.mid_file,s.over_file, s.subject_source from sci_horizontal_apply_vertical s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sys_approval_state st on s.state = st.state_code where s.state in ('VERTICAL_OVER_XY_AUDIT','VERTICAL_OVER_KYC_AUDIT')
AND YEAR(DATE_ADD(COALESCE(s.validity_data, s.signing_data), INTERVAL 1 MONTH)) = #{year}
and top_name like concat('%', #{topName}, '%') and d.dept_name like concat('%', #{dname}, '%') and u.user_name like concat('%', #{userName}, '%') and state = #{state} ${params.dataScope} order by case -- 待学院审核 when state = 'VERTICAL_OVER_XY_AUDIT' then 1 -- 学院通过 when state = 'VERTICAL_OVER_KYC_AUDIT' then 2 end, s.createtime desc

select #{uid} uid,s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type, s.signing_data, s.validity_data, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.state,st.state_name,s.file,s.open_file,s.mid_file,s.over_file, s.subject_source from sci_horizontal_apply_vertical s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sys_approval_state st on s.state = st.state_code where s.state in ('VERTICAL_OVER_JYS_AUDIT','VERTICAL_OVER_XY_AUDIT','VERTICAL_OVER_KYC_AUDIT','VERTICAL_OVER_REJECTED')
AND YEAR(DATE_ADD(COALESCE(s.validity_data, s.signing_data), INTERVAL 1 MONTH)) = #{year}
and top_name like concat('%', #{topName}, '%') and p.dept_name like concat('%', #{yname}, '%') and d.dept_name like concat('%', #{dname}, '%') and u.user_name like concat('%', #{userName}, '%') and state = #{state} ${params.dataScope} order by s.createtime desc

select #{uid} uid,s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type, s.signing_data, s.validity_data, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.state,st.state_name,s.file,s.open_file,s.mid_file,s.over_file, s.subject_source from sci_horizontal_apply_vertical s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sys_approval_state st on s.state = st.state_code where s.state = 'VERTICAL_OVER_PASSED'
AND YEAR(DATE_ADD(s.signing_data, INTERVAL 1 MONTH)) = #{year}
and top_name like concat('%', #{topName}, '%') and p.dept_name like concat('%', #{yname}, '%') and d.dept_name like concat('%', #{dname}, '%') and u.user_name like concat('%', #{userName}, '%') and state = #{state} ${params.dataScope} order by s.createtime desc

