user_id = #{userId}, top_name = #{topName}, top_number = #{topNumber}, top_type = #{topType}, signing_data = #{signingData}, validity_data = #{validityData}, first_person_id = #{firstPersonId}, second_person_id = #{secondPersonId}, third_person_id = #{thirdPersonId}, fourth_person_id = #{fourthPersonId}, amount = #{amount}, file = #{file}, open_file = #{openfile}, mid_file = #{midfile}, over_file = #{overfile}, state = #{state}, subject_source = #{subjectSource},
where id = #{id}

