top_type = #{topType}, subject_source = #{subjectSource}, top_name = #{topName}, top_number = #{topNumber}, amount = #{amount}, signing_data = #{signingData}, first_person_id = #{firstPersonId}, second_person_id = #{secondPersonId}, third_person_id = #{thirdPersonId}, fourth_person_id = #{fourthPersonId}
where id = #{id}

update sci_horizontal_apply_vertical
