mapper.select:
select #{uid} uid,s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type, s.signing_data, s.validity_data, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.state,st.state_name,s.file,s.over_file, s.subject_source from sci_horizontal_apply_vertical s left join sci_persion_vertical pe on pe.vertical_id = s.id left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sys_approval_state st on s.state = st.state_code where pe.persion_id = #{uid}
and s.state = 'VERTICAL_OVER_PASSED'
and s.state in ('VERTICAL_APPLY_DRAFT','VERTICAL_APPLY_JYS_AUDIT','VERTICAL_APPLY_XY_AUDIT','VERTICAL_APPLY_KYC_AUDIT','VERTICAL_APPLY_REJECTED','VERTICAL_APPLY_PASSED') and s.state != 'VERTICAL_OVER_PASSED'
and s.state in ('VERTICAL_OVER_DRAFT','VERTICAL_OVER_JYS_AUDIT','VERTICAL_OVER_XY_AUDIT','VERTICAL_OVER_KYC_AUDIT','VERTICAL_OVER_REJECTED')
AND YEAR(DATE_ADD(COALESCE(s.validity_data, s.signing_data), INTERVAL 1 MONTH)) = #{year}
and d.dept_name like concat('%', #{dname}, '%') and top_name like concat('%', #{topName}, '%') and u.user_name like concat('%', #{userName}, '%') order by case -- 草稿箱 when state = 'VERTICAL_APPLY_DRAFT' then 1 -- 被驳回 when state = 'VERTICAL_APPLY_REJECTED' then 2 -- 审核中 when state in ('VERTICAL_APPLY_JYS_AUDIT','VERTICAL_APPLY_XY_AUDIT','VERTICAL_APPLY_KYC_AUDIT') then 3 -- 申请结项 when state = 'VERTICAL_APPLY_PASSED' then 4 end, s.createtime desc

select s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type,  s.signing_data,  s.first_person_id,  s.second_person_id, s.third_person_id, s.fourth_person_id, concat( s.amount,'万') amount, s.state,s.file,s.open_file,s.mid_file,s.over_file,s.createtime, s.subject_source
from  sci_horizontal_apply_vertical s left join sys_user u on  s.user_id=u.user_id
left join sys_dept d on u.dept_id = d.dept_id
left join sys_dept p on d.parent_id =p.dept_id
where 1=1

    and s.user_id = #{userId}


    and s.createtime >= #{startTime}


    and s.createtime <= #{endTime}


    AND d.parent_id = #{Pcollege}


    AND p.dept_id = #{college}


    AND d.dept_id = #{major}


    and u.tea_zhicheng =#{jobTitle}


    and s.top_name like concat('%', #{topicName}, '%')


    and s.state in (3,5,7,33,55,77,99)


    and s.state in (1,2,4,11,22,44)


    and s.state in (66,6)

order by s.createtime desc

select s.id, u.user_id as participant_user_id, p.dept_name yname, d.dept_name dname, u.login_name, u.user_name userName, s.subject_source, s.top_name, concat( s.amount, '万') amount, susv.change_value , susv.change_status, spv.ranking, s.signing_data, s.validity_data, s.state from sci_horizontal_apply_vertical s left join sys_user u on (s.second_person_id = u.user_id or s.first_person_id=u.user_id or s.third_person_id=u.user_id or s.fourth_person_id=u.user_id ) left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id left join sci_user_score_vertical susv on (s.id = susv.vertical_id and u.user_id=susv.user_id) left join sci_persion_vertical spv on (s.id=spv.vertical_id and u.user_id=spv.persion_id) where 1=1
and d.parent_id =#{college}
AND d.dept_id = #{major}
AND u.user_id = #{teacherName}
and s.createtime >= #{startTime}
and s.createtime <= #{endTime}
and s.top_name like concat('%', #{topicName}, '%')
and s.state in (3,5,7,33,55,77,99)
and s.state in (1,2,4,11,22,44)
and s.state in (66,6)
AND (YEAR(DATE_ADD(s.signing_data, INTERVAL 1 MONTH)) = #{year} OR YEAR(DATE_ADD(s.validity_data, INTERVAL 1 MONTH)) = #{year})
${_dataScope}
and s.top_name is not null and susv.change_status is not NULL order by yname asc, dname asc, u.login_name asc
